import { RichValue } from "@/registry/p1/internal/rich";
import "./pull-quote.css";

export interface PullQuoteProps {
  quote: string;
  cite: string;
  accent: "yellow rule" | "quote mark" | "none";
  align: "center" | "left";
}

export function PullQuoteRender({ quote, cite, accent, align }: PullQuoteProps) {
  return (
    <div className="p1-pull-quote p1-block" data-align={align} data-accent={accent}>
      <div className="p1-pull-quote__inner">
        <blockquote className="p1-pull-quote__blockquote">
          {accent === "yellow rule" && <div className="p1-pull-quote__rule" />}
          {accent === "quote mark" && <div className="p1-pull-quote__mark" aria-hidden="true">&ldquo;</div>}
          <div className="p1-pull-quote__text">
            <RichValue value={quote} />
          </div>
          {cite && <cite className="p1-pull-quote__cite">&mdash; {cite}</cite>}
        </blockquote>
      </div>
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { PullQuoteRender, type PullQuoteProps } from "./pull-quote";
export type { PullQuoteProps };

export const PullQuoteBlock: ComponentConfig<PullQuoteProps> = {
  fields: {
    quote: {
      type: "richtext" as const,
      contentEditable: true,
      visible: false,
      ai: {
        instructions:
          "A memorable pull quote, 15–35 words. May use <mark> to highlight 2–5 key words. No other formatting.",
      },
    },
    cite: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Attribution. Format: Full Name, Role or Title." },
    },
    accent: {
      type: "select" as const,
      options: [
        { label: "Yellow rule", value: "yellow rule" },
        { label: "Quote mark", value: "quote mark" },
        { label: "None", value: "none" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Center", value: "center" },
        { label: "Left", value: "left" },
      ],
    },
  },
  defaultProps: {
    quote:
      "The best workflow is the one your whole team <mark>actually uses</mark> — not the one that looks impressive in a diagram.",
    cite: "Jordan Ellis, Operations Lead",
    accent: "yellow rule",
    align: "center",
  },
  render: PullQuoteRender,
};

export const meta = defineMeta({
  title: 'Pull Quote',
  description: 'Large typographic blockquote with optional yellow rule or quotation mark accent and attribution; use for editorial emphasis quotes.',
  categories: ["editorial"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-rich"],
});

.p1-pull-quote__inner {
  margin-inline: auto;
  max-inline-size: var(--p1-container-narrow);
  padding-block: var(--p1-space-xl);
  padding-inline: var(--p1-space-lg);
}

.p1-pull-quote[data-align="center"] .p1-pull-quote__blockquote { text-align: center; }

.p1-pull-quote__rule {
  background-color: var(--p1-warning);
  block-size: 0.375rem;
  border-radius: var(--p1-radius-pill);
  inline-size: 4rem;
  margin-block-end: var(--p1-space-lg);
}
.p1-pull-quote[data-align="center"] .p1-pull-quote__rule { margin-inline: auto; }

.p1-pull-quote__mark {
  color: color-mix(in oklch, var(--p1-accent) 30%, transparent);
  font-size: 5rem;
  font-style: italic;
  font-weight: 800;
  line-height: 0.5;
  margin-block-end: var(--p1-space-md);
}
.p1-pull-quote[data-align="center"] .p1-pull-quote__mark { text-align: center; }

.p1-pull-quote__text {
  font-size: var(--p1-text-2xl);
  font-style: italic;
  font-weight: var(--p1-weight-medium);
  line-height: var(--p1-leading-tight);
  margin-block-end: var(--p1-space-md);
  text-wrap: balance;
}
@media (width >= 48rem) {
  .p1-pull-quote__text { font-size: var(--p1-text-3xl); }
}

.p1-pull-quote__text [data-richvalue] > * { margin-block: 0; }
.p1-pull-quote__text mark {
  background-color: color-mix(in oklch, var(--p1-warning) 40%, transparent);
  border-radius: 0.125rem;
  padding-inline: 0.125rem;
}

.p1-pull-quote__cite {
  color: var(--p1-accent);
  font-style: normal;
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.04em;
}

